  function buildShell(){
    $("settingsView").innerHTML=`<aside class="settings-sidebar" aria-label="Settings navigation">
      <button id="settingsBack" class="settings-back">${back}<span>Back to company</span></button>
      <button id="settingsPagePicker" class="settings-page-picker" type="button" aria-label="Choose settings page" aria-haspopup="menu"><span>${escape(state.section)}</span>${menuChevron}</button>
      <div class="settings-sidebar-heading" aria-hidden="true">Settings</div>
      <div class="settings-search-row"><label class="settings-search"><svg viewBox="0 0 20 20" aria-hidden="true"><circle cx="8.5" cy="8.5" r="5"/><path d="m12.3 12.3 4 4"/></svg><input id="settingsSearch" type="search" aria-label="Search settings" placeholder="Search settings…"></label><button id="settingsSearchScope" type="button" aria-label="Search all settings" title="Search all settings">${sectionIcons.General}</button></div>
      <div class="settings-theme" id="settingsTheme" role="group" aria-label="Color theme"><button type="button" data-theme-choice="light">Light</button><button type="button" data-theme-choice="dark">Dark</button><button type="button" data-theme-choice="system">Auto</button></div>
      <div class="settings-scope"><span class="settings-scope-label">Applies to</span><button type="button" id="settingsScope" class="menu-select" aria-label="Settings scope" data-value="global"><span>Company defaults</span>${menuChevron}</button></div>
      <nav id="settingsNav" class="settings-nav" aria-label="Settings pages"></nav>
      <button id="settingsGuide" class="settings-guide-button"><svg viewBox="0 0 20 20" aria-hidden="true"><circle cx="10" cy="10" r="7"/><path d="M8.5 8a1.7 1.7 0 1 1 2.4 1.6c-.7.3-.9.8-.9 1.4M10 14v.1"/></svg><span>Guide &amp; help</span></button>
      </aside><main id="settingsMain" class="settings-main"><div id="settingsContent" class="settings-content"></div></main>`;
    $("settingsBack").onclick=close;
    $("settingsSearch").oninput=(event)=>{state.query=event.target.value.trim();clearTimeout(state.searchTimer);state.searchTimer=setTimeout(runSearch,180);};
    $("settingsSearchScope").onclick=()=>{state.searchScope=state.searchScope==="all"?"section":"all";updateSearchChrome();if(state.query)runSearch();};
    $("settingsScope").onclick=()=>{const options=scopeOptions();ui.openMenuSelect($("settingsScope"),options,scopeKey(),(value)=>{const [kind,id]=value.split(":");state.scope=kind==="global"?{kind:"global"}:{kind,id};loadSnapshot();});};
    $("settingsGuide").onclick=renderGuide;
    $("settingsTheme").onclick=(event)=>{const choice=event.target.closest("[data-theme-choice]")?.dataset.themeChoice;if(!choice)return;applyThemeChoice(choice);};
    $("settingsNav").onclick=(event)=>{const button=event.target.closest("button[data-section]");if(button)navigateSection(button.dataset.section);};
    $("settingsPagePicker").onclick=()=>ui.openMenuSelect($("settingsPagePicker"),[...availableNavGroups().flatMap(([group,sections])=>sections.map((section)=>[section,section,group,group])),["Connections & skills","Connections & skills"],["guide","Settings guide"]],state.route==="guide"?"guide":state.section,(value)=>value==="guide"?renderGuide():navigateSection(value),{search:true,minWidth:300,searchPlaceholder:"Find a settings page",searchLabel:"Find a settings page"});
    $("settingsContent").onclick=contentClick;$("settingsContent").onchange=contentChange;
    if(!$("settingsContent").dataset.watched){$("settingsContent").dataset.watched="1";new MutationObserver(()=>finishPaint()).observe($("settingsContent"),{childList:true,subtree:true});}
    updateSearchChrome();
    paintTheme();
  }
  async function open(event={}){if(document.body.classList.contains("onboarding-open"))return;window.PhoenixConversation?.closeInspectionSidebar?.();const detail=event?.detail||event||{};if(detail.section)state.section=detail.section;if(detail.route)state.route=detail.route;if(detail.scope)state.scope=detail.scope;forceCompanyScopeForSection();state.open=true;$("settingsView").hidden=false;document.body.classList.add("settings-open");window.dispatchEvent(new CustomEvent("phoenix:settings-visibility",{detail:{open:true}}));if(!$("settingsNav"))buildShell();renderScope();await loadSnapshot();}
  function close(){state.open=false;$("settingsView").hidden=true;state.route=null;document.body.classList.remove("settings-open");window.dispatchEvent(new CustomEvent("phoenix:settings-visibility",{detail:{open:false}}));}
  function updateSearchChrome(){const button=$("settingsSearchScope"),input=$("settingsSearch");if(!button||!input)return;const local=state.searchScope==="section";button.classList.toggle("local",local);button.innerHTML=local?sectionIcon(state.section):sectionIcons.General;button.setAttribute("aria-label",local?`Search ${state.section} only`:"Search all settings");button.title=local?`Searching ${state.section} only`:"Searching all settings";input.placeholder=local?`Search ${state.section.toLowerCase()}…`:"Search settings…";}
  function forceCompanyScopeForSection(){if(state.section!=="Appearance"||state.scope.kind==="global")return false;state.scope={kind:"global"};renderScope();return true;}
  function scopeOptions(){if(state.section==="Appearance")return [["global","Company appearance"]];return [["global","Company defaults"],...liveAgents().map((agent)=>[`agent:${agent.agent_id}`,agent.display_name]),...(ui.state.view?.directory.groups||[]).filter((group)=>!group.lifecycle||group.lifecycle==="active").map((group)=>[`group:${group.group_id}`,group.name])];}
  // Coworkers in the trash (pending deletion) or archived never appear in pickers or lane lists.
  function liveAgents(){return (ui.state.view?.directory.agents||[]).filter((agent)=>!agent.lifecycle||agent.lifecycle==="active");}
  function renderScope(){const options=scopeOptions(),current=scopeKey(),label=options.find((item)=>item[0]===current)?.[1]||"Company defaults",button=$("settingsScope");if(!button)return;button.dataset.value=current;button.querySelector("span").textContent=label;}
