  function sectionDescription(section){const map={General:"Core application behavior and local data controls.",Composer:"How messages are written, sent, and scoped.","Agents & Groups":"How coworkers collaborate, call one another, and inherit company policy.","Models & Providers":"Choose models and manage your accounts.","Usage & cost":"Reported tokens, cache behavior, time, and provider-reported spend across the company.",Skills:"Playbooks from skills.sh. Phoenix follows these instead of improvising a craft.",Composio:"The consumer key and the apps Phoenix can actually act through.",MCP:"Local commands and remote URLs the company can call as tools.","Remote runners":"Pinned SSH machines for deliberate Workspace-mode execution.",Permissions:"What Phoenix may do automatically and when it must ask.","Browser & Accounts":"Private coworker browsers, login help, cookies, and account creation.",Passes:"Logins, cards, and keys — encrypted on this device. Saving never needs your password; viewing or using one unlocks once per session.",Notifications:"Desktop alerts, sounds, badges, and attention events.",Memory:"Librarian, indexer, retention, and company sharing.","Workflows & Routines":"Taught work, reliability, correction, sharing, and retirement.",Schedules:"Recurring and delayed work, owners, and pause state.",Prompts:"Phoenix and coworker instruction overlays.",Voice:"Microphone, transcription, and spoken replies.",Appearance:"Theme, background, motion, type, and interface density.",Advanced:"Integrations, diagnostics, detailed receipts, and runtime controls."};return escape(map[section]||"Searchable Phoenix configuration.");}
