      "Browser & Accounts":[["Browser behavior",["browser.enabled","browser.headless","browser.suspend_after_seconds","browser.profile_source"]],["Logins & website accounts",["browser.cookie_import_source","browser.account_creation","browser.auto_solve_captcha","browser.automatic_2fa_handoff"]]],
