  function iconStyleComparison(){const agents=(ui.state.view?.directory.agents||[]).slice(0,4),row=state.snapshot.settings.find((entry)=>entry.definition.key==="appearance.coworker_icon_style"),value=row?.value||"flame_crests",enabled=row?.enabled!==false,styles=[{id:"flame_crests",name:"Rising fire",note:"Campfire with side tongues"},{id:"bird_family",name:"Winged fire",note:"The Phoenix mark, tinted"},{id:"character_glyphs",name:"Split crest",note:"Two plumes from one ember"}];return`<section class="settings-section icon-family-section"><h2>Default coworker fire</h2><p class="settings-section-note">${enabled?"New coworkers start here; their saved face, expression, accessory, or custom image stays individual.":"Preview only here. Switch to Company defaults to change the fallback fire."}</p><div class="icon-family-grid">${styles.map((style)=>`<button class="icon-family-card ${value===style.id?"selected":""}" data-icon-style="${style.id}" ${enabled?"":"disabled"}><span class="icon-family-samples">${agents.map((agent)=>`<i>${ui.avatarSvg(agent,"agent",style.id)}</i>`).join("")}</span><span><strong>${style.name}</strong><small>${style.note}</small></span>${value===style.id?ui.checkIcon:""}</button>`).join("")}</div></section>`;}
