  async function saveSetting(key,value,rowNode){if(window.__PHOENIX_ISOLATED_BACKEND__?.current===true&&key==='appearance.reduce_transparency'){try{await ui.invoke('mc_transparency',{enabled:!value});document.documentElement.dataset.mcGlass=String(!value);document.documentElement.dataset.opaque=String(value);const row=state.snapshot.settings.find(r=>r.definition.key===key);if(row)row.value=value;render();}catch(error){ui.toast(error.message||String(error),true);}return;}rowNode?.querySelector(".setting-control")?.insertAdjacentHTML("afterbegin",'<i class="setting-saving"></i>');try{const reply=await rpc({Settings:{action:"set",key,value,scope:state.scope,expected_revision:state.snapshot.revision}});state.snapshot=reply.Settings.snapshot;if(state.scope.kind==="global"){applyLiveSetting(key,value);hydrateConversationSettings();}else if(scopeMatchesSelected(state.scope))applySnapshotLive(state.snapshot);render();}catch(error){ui.toast(error.message,true);await loadSnapshot();}}
