    const key=event.target.closest("[data-reset]")?.closest(".setting-row")?.dataset.key;if(key){resetSetting(key);return;}
    if(event.target.closest("[data-section-back]")){state.route=null;render();return;}
    const guide=event.target.closest("[data-guide-section]")?.dataset.guideSection;if(guide){navigateSection(guide);return;}
    const directoryAction=event.target.closest("[data-directory-action]");if(directoryAction){const item={kind:directoryAction.dataset.kind,id:directoryAction.dataset.id},action=directoryAction.dataset.directoryAction;if(action==="edit")ui.configureItem?.(item);if(action==="delete")ui.deleteItem?.(item);if(action==="create")ui.createItem?.(directoryAction.dataset.kind);return;}
