  const modelLabels={phoenix:"Phoenix",orchestrator:"Phoenix",specialist:"Coworker default",volume_worker:"Volume workers",librarian:"Librarian & indexer",vision:"Visual understanding",image:"Image generation",memory:"Memory summaries",stt:"Speech to text",tts:"Spoken replies",realtime:"Realtime voice"};
  const modelNotes={phoenix:"Coordinates the company and handles your direct requests.",specialist:"New coworkers inherit this route until you give them an override.",volume_worker:"Rare parallel batches of temporary generic workers.",librarian:"Keeps company memory searchable without appearing as a coworker.",vision:"Reads screenshots, pages, and other visual input.",image:"Creates and edits visual assets.",memory:"Compresses older thread context into durable summaries.",stt:"Turns microphone input into text.",tts:"Reads replies aloud.",realtime:"Runs low-latency voice conversations."};
  function fallbackLane(lane){return lane==="phoenix"?"orchestrator":lane;}
  function modelLane(lane){return state.models?.lanes.find((item)=>item.lane===lane)||null;}
  function modelAgent(lane){return(ui.state.view?.directory.agents||[]).find((agent)=>agent.agent_id===lane)||null;}
  function modelLabel(lane){return modelLabels[lane]||agentName(lane).replaceAll("_"," ");}
  function modelNote(lane,inherited=false){const agent=modelAgent(lane);return inherited?`Inherits Coworker default · ${agent?.role_title||"no individual override"}`:modelNotes[lane]||agent?.role_title||"Individual coworker route";}
  function providerFor(id){return state.models?.providers.find((provider)=>provider.id===id);}
